    self, tname: str, schema: str | None
) -> list[ReflectedCheckConstraint]:
    return self._return_from_cache(
        tname,
        schema,
        "alembic_check_constraints",
        self.inspector.get_check_constraints,
        apply_constraint_conv=True,
        optional=False,
